<template><div class="page"><div class="page-header"><div><div class="page-title">追责管理</div><div class="page-note">异常清场问题的责任确认、整改跟踪和归档管理。</div></div></div><div class="filters"><el-select v-model="query.status" placeholder="全部状态" clearable @change="load"><el-option v-for="(v,k) in statusText" :key="k" :label="v" :value="k"/></el-select><el-input v-model="query.keyword" clearable placeholder="追责单号、铺位、商户或责任人" @keyup.enter="load"/><el-button type="primary" @click="load">查询</el-button></div><el-table :data="rows" v-loading="loading" border><el-table-column prop="orderNo" label="追责单号" min-width="190"/><el-table-column prop="periodDate" label="日清日期" width="115"/><el-table-column prop="stallCode" label="铺位" width="105"/><el-table-column prop="merchantName" label="商户" min-width="150"/><el-table-column prop="issueDescription" label="异常问题" min-width="220" show-overflow-tooltip/><el-table-column prop="responsibleName" label="责任人" width="105"><template #default="{row}">{{row.responsibleName||'待确认'}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="tagType(row.status)">{{statusText[row.status]||row.status}}</el-tag></template></el-table-column><el-table-column label="整改期限" width="175"><template #default="{row}">{{formatDateTime(row.deadlineAt)}}</template></el-table-column><el-table-column label="操作" width="160" fixed="right"><template #default="{row}"><el-button link @click="openDetail(row.id)">{{canManage?'处理':'查看'}}</el-button><el-button link @click="print(row.id)">打印</el-button></template></el-table-column></el-table>
<el-dialog v-model="visible" :title="canManage?'处理追责单':'查看追责单'" width="720px"><el-descriptions v-if="detail.id" :column="2" border><el-descriptions-item label="追责单号" :span="2">{{detail.orderNo}}</el-descriptions-item><el-descriptions-item label="铺位">{{detail.stallCode}}</el-descriptions-item><el-descriptions-item label="商户">{{detail.merchantName||'-'}}</el-descriptions-item><el-descriptions-item label="检查人">{{detail.inspectorName}}</el-descriptions-item><el-descriptions-item label="检查时间">{{formatDateTime(detail.inspectedAt)}}</el-descriptions-item><el-descriptions-item label="异常问题" :span="2">{{detail.issueDescription}}</el-descriptions-item></el-descriptions><el-form class="handle-form" label-width="90px"><el-form-item label="责任人"><el-input v-model="detail.responsibleName" :disabled="!canManage"/></el-form-item><el-form-item label="联系电话"><el-input v-model="detail.responsiblePhone" :disabled="!canManage"/></el-form-item><el-form-item label="整改要求"><el-input v-model="detail.correctiveAction" type="textarea" :rows="3" :disabled="!canManage"/></el-form-item><el-form-item label="整改期限"><el-date-picker v-model="detail.deadlineAt" type="datetime" value-format="YYYY-MM-DD HH:mm:ss" :disabled="!canManage"/></el-form-item><el-form-item label="处理状态"><el-select v-model="detail.status" :disabled="!canManage"><el-option v-for="(v,k) in statusText" :key="k" :label="v" :value="k"/></el-select></el-form-item><el-form-item label="处理结果"><el-input v-model="detail.handlingResult" type="textarea" :rows="3" :disabled="!canManage"/></el-form-item></el-form><template #footer><el-button @click="visible=false">关闭</el-button><el-button @click="print(detail.id)">打印</el-button><el-button v-if="canManage" type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup lang="ts">import{computed,onMounted,reactive,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{ElMessage}from'element-plus';import{operationAccountabilityApi}from'@/api/operation';import{formatDateTime}from'@/utils/format';import{useUserStore}from'@/stores/user';const statusText:Record<string,string>={PENDING:'待处理',PROCESSING:'处理中',RESOLVED:'已整改',CLOSED:'已关闭'},query=reactive({status:'',keyword:''}),rows=ref<any[]>([]),detail=reactive<any>({}),visible=ref(false),loading=ref(false),saving=ref(false),route=useRoute(),router=useRouter(),user=useUserStore(),canManage=computed(()=>user.hasPermission('operation.accountability.manage'));function tagType(s:string){return s==='CLOSED'?'success':s==='RESOLVED'?'warning':s==='PROCESSING'?'primary':'danger'}async function load(){loading.value=true;try{rows.value=(await operationAccountabilityApi.list(query)as any)||[]}finally{loading.value=false}}async function openDetail(id:number){Object.assign(detail,await operationAccountabilityApi.detail(id));visible.value=true}async function save(){saving.value=true;try{Object.assign(detail,await operationAccountabilityApi.update(detail.id,detail));ElMessage.success('追责单已保存');visible.value=false;await load()}finally{saving.value=false}}function print(id:number){router.push(`/operation/accountability/${id}/print`)}onMounted(async()=>{await load();const id=Number(route.query.open);if(id)openDetail(id)});</script>
<style scoped>.page-note{color:#909399;margin-top:6px;font-size:13px}.filters{display:flex;gap:10px;margin-bottom:16px}.filters .el-select{width:150px}.filters .el-input{width:320px}.handle-form{margin-top:18px}@media(max-width:768px){.filters{display:grid;grid-template-columns:1fr auto}.filters .el-select,.filters .el-input{width:100%}.filters .el-select{grid-column:1/-1}.page{overflow-x:auto}}</style>
